const response = $input.first().json;
const emailMeta = $("Pre-process & Sanitize Email").first().json;

let aiOutput = {};
try {
  const content = response.choices[0].message.content;
  aiOutput = typeof content === 'string' ? JSON.parse(content) : content;
} catch (err) {
  aiOutput = {
    category: 'Urgent Inquiry',
    urgency_score: 3,
    summary: 'Could not parse JSON response from AI Gateway.',
    action_needed: 'Check email manually.',
    draft_reply: 'Hi, thank you for reaching out. I received your message and will get back to you shortly.'
  };
}

// Determine emoji badge based on urgency
const urgencyBadge = '⚡'.repeat(Math.min(aiOutput.urgency_score || 1, 5));

// Format telegram markdown message
const telegramText = `📬 *New Inbound Email Analyzed*\n` +
`*From:* \`${emailMeta.from}\`\n` +
`*Subject:* *${emailMeta.subject}*\n` +
`*Category:* ${aiOutput.category} (${urgencyBadge})\n\n` +
`📋 *Executive Summary:*\n${aiOutput.summary}\n\n` +
`🎯 *Action Needed:*\n${aiOutput.action_needed}\n\n` +
`✍️ *Suggested Draft Reply:*\n\"_${aiOutput.draft_reply}_\"`;

return [{
  json: {
    ...emailMeta,
    ai: aiOutput,
    telegramText,
    sendCallback: `send:${emailMeta.threadId.slice(0, 40)}`
  }
}];

const query = $input.first().json.callback_query;
const originalText = query.message.text || '';
const messageId = query.message.message_id;
const chatId = query.message.chat.id;

// 1. Extract recipient email
const fromMatch = originalText.match(/From:\s*([^\n\r]+)/i);
const rawFrom = fromMatch ? fromMatch[1].trim() : '';
const emailBracket = rawFrom.match(/<([^>]+)>/);
const toEmail = emailBracket ? emailBracket[1].trim() : rawFrom.replace(/`/g, '').trim();

// 2. Extract original subject
const subjMatch = originalText.match(/Subject:\s*([^\n\r]+)/i);
let subject = subjMatch ? subjMatch[1].replace(/\*/g, '').trim() : 'Project Inquiry';
const replySubject = subject.toLowerCase().startsWith('re:') ? subject : `Re: ${subject}`;

// 3. Extract the drafted reply text
let draftReply = '';
const draftMarker = 'Suggested Draft Reply:';
const draftIndex = originalText.indexOf(draftMarker);
if (draftIndex !== -1) {
  let raw = originalText.slice(draftIndex + draftMarker.length).trim();
  if (raw.startsWith('"') || raw.startsWith('“')) raw = raw.slice(1);
  const lastQuote = Math.max(raw.lastIndexOf('"'), raw.lastIndexOf('”'));
  if (lastQuote !== -1) raw = raw.slice(0, lastQuote);
  draftReply = raw.trim();
}

return [{
  json: {
    toEmail,
    replySubject,
    draftReply,
    originalText,
    messageId,
    chatId,
    timestamp: new Date().toLocaleTimeString()
  }
}];
